import json
import urllib.request
import urllib.error

API_KEY = os.environ.get('DAYTONA_API_KEY')
API_URL = "https://app.daytona.io/api"

def api_request(method, path, data=None):
    url = f"{API_URL}{path}"
    headers = {
        'Authorization': f'Bearer {API_KEY}',
        'Content-Type': 'application/json'
    }
    req = urllib.request.Request(url, method=method, headers=headers)
    if data:
        req.data = json.dumps(data).encode('utf-8')
    try:
        with urllib.request.urlopen(req) as response:
            return json.loads(response.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        print(f"HTTP Error: {e.code} - {e.read().decode('utf-8')}")
        raise

def main():
    # List sandboxes
    print("Listing sandboxes...")
    sandboxes = api_request('GET', '/sandbox')
    print(f"Found {len(sandboxes)} sandboxes")
    for sb in sandboxes:
        print(f"  ID: {sb.get('id')}, State: {sb.get('state')}, Target: {sb.get('target')}")

    # Create a sandbox
    print("\nCreating sandbox...")
    new_sandbox = api_request('POST', '/sandbox', {})
    print(f"Created sandbox: {new_sandbox.get('id')}")
    print(f"State: {new_sandbox.get('state')}")
    print(f"Toolbox URL: {new_sandbox.get('toolboxProxyUrl')}")

    sandbox_id = new_sandbox.get('id')

    # Try to execute a command via API
    print("\nExecuting command via API...")
    try:
        result = api_request('POST', f'/sandbox/{sandbox_id}/toolbox/process/exec', {
            'command': "echo 'Hello, World!'"
        })
        print(f"Result: {result}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
"}

